import type { GamesApi } from "../../api";
import type { DataItem, Dataset } from "../../core/types";
import { decode, type WordsDataFile } from "./codec";
// generated by `bun run src/cli.ts data words`; text, so it is parsed as JSON rather than as code
import raw from "./data.json" with { type: "text" };

declare module "../../core/types" {
  interface Datasets {
    words: Dataset;
  }
}

/** Answers: common, spelled the same in american and british english, not offensive. */
const ANSWER = "common<=35 spelling:us spelling:gb !offensive";

/**
 * English words for word games: every SCOWL word up to size 80 is a fair guess; the pools give
 * common words to draw answers from.
 */
export default function pack(games: GamesApi): void {
  const file = JSON.parse(raw as unknown as string) as WordsDataFile;
  let items: DataItem[] | null = null;
  const dataset: Dataset = {
    id: "words",
    name: "english words",
    version: file.version,
    credits: file.credits,
    attributes: file.attributes,
    noun: { one: "word", many: "words" },
    spelling: { label: "letters", primary: true, lengths: { min: 5, max: 5 } },
    featured: ["length", "common"],
    // lengths are a game's own setting, so pools don't fix one
    pools: [
      { label: "common words", query: ANSWER },
      { label: "the most common words", query: "common<=20 spelling:us spelling:gb !offensive" },
      { label: "every word", query: "" },
    ],
    items: () => (items ??= decode(file)),
  };
  games.registry.dataset(dataset);
}
